def _post_run_cell(self, result: Any) -> None:
    if not self.recording or not self._capture_stack:
        return
    # Only record cells whose ``pre_run_cell`` we saw: the frame at the
    # top of the stack must belong to this very cell.  ``post_run_cell``
    # without a matching frame happens e.g. for empty cells (for which
    # ``pre_run_cell`` is never triggered) or for the cell that invoked
    # ``%session_bundle start`` itself.
    frame_info = self._capture_stack[-1]["info"]
    if frame_info is not getattr(result, "info", None):
        return
    stdout_text, stderr_text = self._pop_capture_frame()
    try:
        event = self._build_event(result, stdout_text, stderr_text)
    except Exception:
        # Recording must never break the user's session: drop the event
        # if it cannot be built.
        return
    self.events.append(event)
    try:
        self._flush()
    except Exception:
        sys.stderr.write(
            f"Warning: could not update session bundle at {self.path}\n"
        )

def _format_execute_result(self, result: Any) -> Dict[str, Any]:
    obj = getattr(result, "result", None)
    if obj is None:
        return {}
    format_dict: Dict[str, Any] = {}
    try:
        formatted, _md = self.shell.display_formatter.format(obj)
        if formatted:
            format_dict = {
                key: value
                for key, value in formatted.items()
                if isinstance(value, str)
            }
    except Exception:
        format_dict = {}
    if not isinstance(format_dict.get("text/plain"), str):
        try:
            format_dict["text/plain"] = repr(obj)
        except Exception:
            format_dict["text/plain"] = "<unrepresentable object>"
    return format_dict

def _build_event(
    self, result: Any, stdout_text: str, stderr_text: str
) -> Dict[str, Any]:
    info = getattr(result, "info", None)
    code = getattr(info, "raw_cell", None)
    if not isinstance(code, str):
        code = ""
    execution_count = getattr(result, "execution_count", None)
    if not _is_int(execution_count):
        execution_count = None
    success = bool(getattr(result, "success", False))
    event: Dict[str, Any] = {
        "type": "cell",
        "seq": len(self.events) + 1,
        "recorded_at": _utcnow_iso(),
        "execution_count": execution_count,
        "code": code,
        "success": success,
        "stdout": stdout_text,
        "stderr": stderr_text,
        "execute_result": self._format_execute_result(result),
    }
    if not success:
        exception = (
            getattr(result, "error_before_exec", None)
            or getattr(result, "error_in_exec", None)
        )
        if exception is None:
