def apply_redactions(obj: Any, patterns: List[str]) -> Any:
    """Return a copy of *obj* with every literal *pattern* replaced.

    The replacement is applied recursively to every string found in
    dictionaries, lists and tuples; occurrences are substituted with
    :data:`REDACTION_PLACEHOLDER`.
    """
    if not patterns:
        return obj
    if isinstance(obj, str):
        for pattern in patterns:
            if pattern:
                obj = obj.replace(pattern, REDACTION_PLACEHOLDER)
        return obj
    if isinstance(obj, dict):
        return {
            apply_redactions(key, patterns): apply_redactions(value, patterns)
            for key, value in obj.items()
        }
    if isinstance(obj, (list, tuple)):
        return [apply_redactions(item, patterns) for item in obj]
    return obj

